#include <iostream>
#include <string>
#include <sstream>
#include <algorithm>
#include <cctype>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string line;
    bool first_line = true;

    while (std::getline(std::cin, line)) {
        if (first_line) {
            first_line = false;
            continue;
        }

        int ans = 0;
        std::stringstream ss(line);
        std::string word;

        while (ss >> word) {
            int curr = 0;
            for (char ch : word) {
                if (ch >= 'A' && ch <= 'Z') {
                    curr++;
                }
            }
            ans = std::max(ans, curr);
        }

        std::cout << ans << '\n';
    }

    return 0;
}

